import os
import re
import time

from locust import HttpUser, LoadTestShape, constant, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
ITERATIONS = 2

_account_counter = 0

def _next_username():
    global _account_counter
    _account_counter += 1
    return f"bench-{((_account_counter - 1) % 16) + 1}"


class JourneyShape(LoadTestShape):
    def __init__(self, environment):
        super().__init__(environment)
        self.started = False
        self.settled = False

    def tick(self):
        users = 2
        if not self.started:
            self.started = True
            return (users, users)

        if not self.settled:
            if self.runner and self.runner.user_count >= users:
                self.settled = True
                return (users, 0)
            return (users, users)

        if self.runner and self.runner.user_count == 0:
            return None
        return (users, 0)


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = _next_username()
        self.iterations_left = ITERATIONS
        self.reset_state()

    def reset_state(self):
        self.csrf = "MISSING"
        self.cart_id = "MISSING"
        self.etag = "MISSING"
        self.grant_id = "MISSING"
        self.has_cart = False

    @task
    def journey(self):
        if self.iterations_left <= 0:
            raise StopUser()

        self.iterations_left -= 1
        self.reset_state()

        try:
            self.run_journey()
        except StopUser:
            raise
        except Exception:
            # Any unexpected internal error should not spawn more traffic.
            # Locust will still record the last in-flight sample as failed if it failed.
            pass

        if self.iterations_left <= 0:
            raise StopUser()

    def run_journey(self):
        if not self.get_login_form():
            return
        if not self.post_login():
            return
        if not self.fetch_catalog():
            return
        if not self.create_cart():
            return
        if not self.place_order():
            return

    # ---------- raw request helper ----------
    def _request(self, method, path, name, headers=None, json=None, allow_redirects=False):
        headers = headers or {}
        headers.setdefault("Content-Type", "application/json")
        if method.upper() != "GET":
            headers.setdefault("X-CSRF-Token", self.csrf)

        response = self.client.request(
            method,
            path,
            headers=headers,
            json=json,
            catch_response=True,
            allow_redirects=allow_redirects,
            name=name,
        )
        return response

    # ---------- recovery-aware request helper ----------
    def api_request(self, method, path, name, headers=None, json=None, allow_redirects=False):
        headers = headers or {}
        headers.setdefault("Content-Type", "application/json")
        if method.upper() != "GET":
            headers.setdefault("X-CSRF-Token", self.csrf)

        response = self.client.request(
            method,
            path,
            headers=headers,
            json=json,
            catch_response=True,
            allow_redirects=allow_redirects,
            name=name,
        )

        if self._is_expiry_401(response):
            response.success()
            recovered = self._recover_session(response)
            if not recovered:
                response.failure("401 recovery failed")
                return response

            headers["X-CSRF-Token"] = self.csrf
            response = self.client.request(
                method,
                path,
                headers=headers,
                json=json,
                catch_response=True,
                allow_redirects=allow_redirects,
                name=name,
            )

        return response

    def _is_expiry_401(self, response):
        if response.status_code != 401:
            return False
        try:
            data = response.json()
        except Exception:
            return False
        error = data.get("error") or data.get("Error") or ""
        return error in ("expired", "session")

    # ---------- recovery ----------
    def _recover_session(self, response):
        try:
            data = response.json()
        except Exception:
            return False

        error = data.get("error")
        if error == "expired":
            return self._recover_expired()
        if error == "session":
            return self._recover_revoked()
        return False

    def _recover_expired(self):
        renew = self._request("POST", "/v2/session/renew", name="/v2/session/renew", json={})
        if renew.status_code != 200:
            renew.failure(f"renew unexpected status {renew.status_code}")
            return False
        try:
            renew_data = renew.json()
        except Exception:
            renew.failure("renew response invalid JSON")
            return False

        if "csrf" in renew_data:
            self.csrf = renew_data["csrf"]

        if self.has_cart and self.cart_id != "MISSING":
            recover = self._request(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                name="/v2/carts/recover",
                json={},
            )
            if recover.status_code != 200:
                recover.failure(f"cart recover unexpected status {recover.status_code}")
                return False
            try:
                recover_data = recover.json()
            except Exception:
                recover.failure("cart recover invalid JSON")
                return False
            if "csrf" in recover_data:
                self.csrf = recover_data["csrf"]

        return True

    def _recover_revoked(self):
        renew = self._request("POST", "/v2/session/renew", name="/v2/session/renew", json={})
        if renew.status_code == 200:
            try:
                renew_data = renew.json()
                if "csrf" in renew_data:
                    self.csrf = renew_data["csrf"]
            except Exception:
                renew.failure("renew response invalid JSON")
                return False
        else:
            # Renew may fail: get a fresh form/login.
            if not self.get_login_form():
                renew.failure("fresh login form failed after revoked session")
                return False
            if not self.post_login():
                renew.failure("fresh login failed after revoked session")
                return False

        if self.has_cart and self.cart_id != "MISSING":
            recover = self._request(
                "POST",
                f"/v2/carts/{self.cart_id}/recover",
                name="/v2/carts/recover",
                json={},
            )
            if recover.status_code != 200:
                recover.failure(f"cart recover unexpected status {recover.status_code}")
                return False
            try:
                recover_data = recover.json()
            except Exception:
                recover.failure("cart recover invalid JSON")
                return False
            if "csrf" in recover_data:
                self.csrf = recover_data["csrf"]

        return True

    # ---------- authentication flow ----------
    def get_login_form(self):
        response = self._request("GET", "/v2/login-form", name="/v2/login-form")
        if response.status_code != 200:
            response.failure(f"login-form unexpected status {response.status_code}")
            return False

        csrf = self._extract_csrf_from_html(response.text)
        if not csrf:
            response.failure("login-form missing csrf input")
            return False

        self.csrf = csrf
        return True

    def _extract_csrf_from_html(self, html):
        pattern = r"""<input(?=[^>]*\bname=["']csrf["'])(?=[^>]*\bvalue=["']([^"']+)["'])[^>]*>"""
        match = re.search(pattern, html, re.IGNORECASE)
        if match:
            return match.group(1)
        return None

    def post_login(self):
        payload = {"username": self.username, "password": "bench", "csrf": self.csrf}
        response = self._request("POST", "/v2/login", name="/v2/login", json=payload)

        if response.status_code == 200:
            try:
                data = response.json()
            except Exception:
                response.failure("login response invalid JSON")
                return False
            if "csrf" not in data:
                response.failure("login response missing csrf")
                return False
            self.csrf = data.get("csrf", self.csrf)
            return True

        if response.status_code == 302:
            location = response.headers.get("Location")
            if not location:
                response.failure("login 302 without Location")
                return False
            return self.handle_login_redirect(location)

        response.failure(f"login unexpected status {response.status_code}")
        return False

    def handle_login_redirect(self, location):
        response = self._request("GET", location, name="/v2/login-redirect")
        if response.status_code != 200:
            response.failure(f"login redirect unexpected status {response.status_code}")
            return False

        try:
            data = response.json()
        except Exception:
            return self.handle_challenge_form(response)

        if "grant_id" not in data:
            response.failure("login redirect JSON missing grant_id")
            return False

        self.grant_id = data.get("grant_id")
        if "csrf" in data:
            self.csrf = data["csrf"]
        return True

    def handle_challenge_form(self, response):
        html = response.text
        if not html:
            response.failure("empty challenge form")
            return False

        action = self._extract_form_action(html)
        challenge_value = self._extract_challenge_value(html)

        if not action or not challenge_value:
            response.failure("challenge form missing action or challenge input")
            return False

        challenge_response = self._request(
            "POST",
            action,
            name="/v2/challenges",
            json={"challenge": challenge_value},
        )
        if challenge_response.status_code != 302:
            challenge_response.failure(
                f"challenge POST expected 302, got {challenge_response.status_code}"
            )
            return False

        location = challenge_response.headers.get("Location")
        if not location:
            challenge_response.failure("challenge POST missing Location")
            return False

        grant_response = self._request(
            "GET", location, name="/v2/challenge-redirect"
        )
        if grant_response.status_code != 200:
            grant_response.failure(
                f"challenge redirect unexpected status {grant_response.status_code}"
            )
            return False

        try:
            data = grant_response.json()
        except Exception:
            grant_response.failure("challenge redirect invalid JSON")
            return False

        if "grant_id" not in data:
            grant_response.failure("challenge redirect missing grant_id")
            return False

        self.grant_id = data.get("grant_id")
        if "csrf" in data:
            self.csrf = data["csrf"]
        return True

    def _extract_form_action(self, html):
        match = re.search(r"""<form\b[^>]*\saction=["']([^"']+)["']""", html, re.IGNORECASE)
        return match.group(1) if match else None

    def _extract_challenge_value(self, html):
        patterns = [
            r"""<input\b[^>]*\bname=["']challenge["'][^>]*\bvalue=["']([^"']+)["']""",
            r"""<input\b[^>]*\bvalue=["']([^"']+)["'][^>]*\bname=["']challenge["']""",
        ]
        for pattern in patterns:
            match = re.search(pattern, html, re.IGNORECASE)
            if match:
                return match.group(1)
        return None

    # ---------- catalog ----------
    def fetch_catalog(self):
        response = self.api_request("GET", "/v2/catalog", name="/v2/catalog")
        if response.status_code != 200:
            response.failure(f"catalog unexpected status {response.status_code}")
            return False

        try:
            data = response.json()
            products = data["data"]["products"]
        except Exception:
            response.failure("catalog response missing data.products")
            return False

        product_id = None
        variant_id = None
        for product in products:
            variants = product.get("variants") or []
            if variants and variants[0].get("in_stock") is True:
                product_id = product.get("id")
                variant_id = variants[0].get("id")
                break

        if product_id is None or variant_id is None:
            response.failure("catalog has no in-stock product")
            return False

        self.product_id = product_id
        self.variant_id = variant_id
        return True

    # ---------- carts ----------
    def create_cart(self):
        payload = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id != "MISSING":
            payload["grant_id"] = self.grant_id

        response = self.api_request("POST", "/v2/carts", name="/v2/carts", json=payload)

        if response.status_code != 201:
            response.failure(f"carts unexpected status {response.status_code}")
            return False

        try:
            data = response.json()
            cart_id = data.get("id")
        except Exception:
            response.failure("carts response invalid JSON")
            return False

        if not isinstance(cart_id, str) or not cart_id.startswith("cart-"):
            response.failure("carts response missing valid id")
            return False

        self.cart_id = cart_id
        self.has_cart = True
        if "csrf" in data:
            self.csrf = data["csrf"]

        etag = response.headers.get("ETag")
        if etag:
            self.etag = etag

        return True

    # ---------- orders ----------
    def place_order(self):
        payload = {"cart_id": self.cart_id}
        headers = {"Idempotency-Key": self.cart_id}
        if self.etag != "MISSING":
            headers["If-Match"] = self.etag

        response = self.api_request(
            "POST", "/v2/orders", name="/v2/orders", json=payload, headers=headers
        )

        if response.status_code == 201:
            try:
                data = response.json()
            except Exception:
                response.failure("orders response invalid JSON")
                return False

            if data.get("accepted") is not True:
                response.failure("orders accepted false")
                return False

            if "csrf" in data:
                self.csrf = data["csrf"]

            return True

        if response.status_code == 200:
            response.failure("orders accepted false (business failure)")
            return False

        response.failure(f"orders unexpected status {response.status_code}")
        return False
