        name = get_attr(tag, "name")
        if name and name.lower() == "csrf":
            return get_attr(tag, "value")
    return None


def parse_body(resp):
    try:
        data = resp.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def build_schedule(t0):
    times = []
    t = 0.0

    # Warmup [0,5): 5/s
    while t < 5.0:
        times.append(t0 + t)
        t += 0.2

    # Scored plateau 1 [5,15): 5/s
    while t < 15.0:
        times.append(t0 + t)
        t += 0.2

    # Scored plateau 2 [15,25): 15/s
    while t < 25.0:
        times.append(t0 + t)
        t += 1.0 / 15.0

    # Scored plateau 3 [25,35): 5/s
    while t < 35.0:
        times.append(t0 + t)
        t += 0.2

    return times


def next_due():
    global T0, SCHEDULE, NEXT_SLOT
    if T0 is None:
        T0 = time.time()
        SCHEDULE = build_schedule(T0)
        NEXT_SLOT = 0

    if NEXT_SLOT >= len(SCHEDULE):
        return None

    due = SCHEDULE[NEXT_SLOT]
    NEXT_SLOT += 1
    return due


def get_retry_after(resp):
    try:
        return float(resp.headers.get("Retry-After", 1.0))
    except Exception:
        return 1.0


class WorkUser(HttpUser):
    wait_time = constant(0)

    def on_start(self):
        global USER_SEQ
        USER_SEQ += 1
        self.username = f"bench-{USER_SEQ}"
        self.csrf = None
        if not self.login():
            raise StopUser()

    def login(self):
        resp = self.client.get(
            "/v2/login-form",
            allow_redirects=False,
            name="/v2/login-form",
            catch_response=True,
        )
        if resp.status_code != 200:
            resp.failure(f"login form status {resp.status_code}")
            return False

        form_csrf = extract_csrf(resp.text)
        if not form_csrf:
            resp.failure("login form missing csrf")
            return False

        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": form_csrf},
            allow_redirects=False,
            name="/v2/login",
            catch_response=True,
        )

        if resp.status_code in (301, 302, 303, 307, 308):
            loc = resp.headers.get("Location")
            if not loc:
                resp.failure("login redirect missing Location")
                return False
            base = self.client.base_url or os.environ.get("BASE_URL", "http://127.0.0.1:8000")
            resp = self.client.get(
                urljoin(base, loc),
                allow_redirects=False,
                name="/v2/login-final",
                catch_response=True,
            )

        if resp.status_code != 200:
            resp.failure(f"login status {resp.status_code}")
            return False

        data = parse_body(resp)
        csrf = data.get("csrf")
        if not csrf:
            resp.failure("login response missing csrf")
            return False

        self.csrf = csrf
        return True

    def renew_session(self):
        if not self.csrf:
            return False

        resp = self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            name="/v2/session/renew",
            catch_response=True,
        )

        if resp.status_code < 400:
            data = parse_body(resp)
            if data.get("csrf"):
                self.csrf = data["csrf"]
            return True

        if resp.status_code != 401:
            resp.failure(f"renew unexpected status {resp.status_code}")
        return False

    def send_work(self):
        return self.client.post(
            "/v2/work",
            json={},
            headers={"X-CSRF-Token": self.csrf},
            allow_redirects=False,
            name="/v2/work",
            catch_response=True,
        )

    def do_work(self):
        request_attempts = 0
        recovery_used = False

        while request_attempts < 5:
            request_attempts += 1
            resp = self.send_work()

            if resp.status_code < 400:
                data = parse_body(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

            if resp.status_code == 429:
                if request_attempts < 5:
                    resp.success()  # scheduled 429 is expected, not a failure
                    retry_after = get_retry_after(resp)
                    gevent.sleep(retry_after)
                    continue
                resp.failure("scheduled 429 retries exhausted")
                return False

            if resp.status_code == 401:
                error = parse_body(resp).get("error")
                if error in ("expired", "session"):
                    resp.success()  # expected expiry, not a failure
                    if recovery_used:
                        resp.failure(f"work 401 {error} after recovery")
                        return False
                    recovery_used = True

