import re
import time
import gevent
from gevent.lock import BoundedSemaphore

from locust import HttpUser, task, LoadTestShape, between
from locust.exception import StopUser


_account_counter = 0
_account_lock = BoundedSemaphore()
_anchor_lock = BoundedSemaphore()
_schedule_lock = BoundedSemaphore()
_anchor_t0 = None
_anchor_set = False
_schedule_times = []
_schedule_idx = 0


def _next_username():
    global _account_counter
    with _account_lock:
        n = _account_counter
        _account_counter += 1
    return f"bench-{n % 16 + 1}"


def _as_json(resp):
    try:
        return resp.json() or {}
    except Exception:
        return {}


def _get_attr(tag, attr):
    m = re.search(
        r"\b" + re.escape(attr) + r"\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))",
        tag,
        re.IGNORECASE,
    )
    if not m:
        return None
    if m.group(1) is not None:
        return m.group(1)
    if m.group(2) is not None:
        return m.group(2)
    return m.group(3)


def _extract_csrf(html):
    if not html:
        return None
    for tag in re.findall(r"<input\b[^>]*>", html, re.IGNORECASE):
        if _get_attr(tag, "name") == "csrf":
            return _get_attr(tag, "value")
    return None


def _parse_retry_after(value):
    try:
        if value is None:
            return 1.0
        return max(0.05, float(value))
    except Exception:
        return 1.0


def _build_schedule(t0):
    times = []
    start = t0 + 5.0
    offset = 0.0

    rate_1 = 5.0
    for _ in range(int(rate_1 * 10)):
        times.append(start + offset)
        offset += 1.0 / rate_1

    rate_2 = 15.0
    for _ in range(int(rate_2 * 10)):
        times.append(start + offset)
        offset += 1.0 / rate_2

    rate_3 = 5.0
    for _ in range(int(rate_3 * 10)):
        times.append(start + offset)
        offset += 1.0 / rate_3

    return times


def _next_schedule_time():
    global _schedule_idx
    while True:
        with _schedule_lock:
            if _schedule_idx >= len(_schedule_times):
                return None
            scheduled = _schedule_times[_schedule_idx]
            _schedule_idx += 1

        now = time.monotonic()
        if scheduled >= now - 0.25:
            return scheduled
        # Missed target by too much; skip it to avoid a burst.


class WorkUser(HttpUser):
    wait_time = between(0, 0)

    def on_start(self):
        self.username = _next_username()
        self.csrf = None
        for _ in range(3):
            if self._login():
                return
        raise StopUser()

    def _login(self):
        with self.client.get("/v2/login-form", allow_redirects=False) as resp:
            if resp.status_code != 200:
                return False
            csrf = _extract_csrf(resp.text)
            if not csrf:
                return False

        headers = {"X-CSRF-Token": csrf, "Content-Type": "application/json"}
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            headers=headers,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if not loc:
                    return False
                with self.client.get(loc, allow_redirects=False) as loc_resp:
                    if loc_resp.status_code not in (200, 201):
                        return False
                    data = _as_json(loc_resp)
                    self.csrf = data.get("csrf")
                    if not self.csrf:
                        self.csrf = _extract_csrf(loc_resp.text)
            elif resp.status_code in (200, 201):
                data = _as_json(resp)
                self.csrf = data.get("csrf")
            else:
                return False

        return bool(self.csrf)

    def _renew(self):
        if not self.csrf:
            return self._login()

        headers = {"X-CSRF-Token": self.csrf, "Content-Type": "application/json"}
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=headers,
            allow_redirects=False,
        ) as resp:
            if resp.status_code == 200:
                data = _as_json(resp)
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True

            if resp.status_code == 302:
                loc = resp.headers.get("Location")
                if loc:
                    with self.client.get(loc, allow_redirects=False) as loc_resp:
                        if loc_resp.status_code < 400:
                            data = _as_json(loc_resp)
                            if data.get("csrf"):
                                self.csrf = data["csrf"]
                            return True
        return False

    def _work_once(self):
        headers = {"X-CSRF-Token": self.csrf or "", "Content-Type": "application/json"}
        start = time.monotonic()
        with self.client.post(
            "/v2/work",
            json={},
            headers=headers,
            allow_redirects=False,
            catch_response=True,
        ) as resp:
            status = resp.status_code
            data = _as_json(resp)

            if status < 400 and data.get("ok") is True:
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                return True, start, resp

            if status == 429:
                return False, start, resp

            if status == 401:
                err = data.get("error")
                if err in ("expired", "session"):
                    return False, start, resp
                if err == "denied":
                    resp.failure("work denied")
                    return False, start, resp
                resp.failure(f"work unexpected 401 error={err}")
                return False, start, resp

            if status < 400:
                resp.failure("work response ok false")
            else:
                resp.failure(f"work HTTP {status}")
            return False, start, resp

    def _perform_work_with_retries(self):
        attempts = 0
        expired_recovered = False
        session_recovered = False

        while attempts < 5:
            ok, start, resp = self._work_once()
            if ok:
                return True, start, resp

            status = resp.status_code
            data = _as_json(resp)

            if status == 429:
                if attempts < 4:
                    retry_after = _parse_retry_after(resp.headers.get("Retry-After"))
                    gevent.sleep(retry_after)
                    attempts += 1
                    continue
                # Scheduled 429s are expected non-completions; do not mark as failure.
                return False, start, resp

            if status == 401:
                err = data.get("error")
                if err == "expired" and not expired_recovered:
                    expired_recovered = True
                    if not self._renew():
                        self._login()
                    attempts += 1
                    continue
                if err == "session" and not session_recovered:
                    session_recovered = True
                    self._login()
                    attempts += 1
                    continue
                # Denied/unknown 401s were already marked as failures in _work_once.
                return False, start, resp

            # Other unexpected failures were already marked.
            return False, start, resp

        return False, time.monotonic(), None

    def _anchor_work(self):
        global _anchor_t0, _anchor_set, _schedule_times

        for _ in range(20):
            ok, start, _ = self._perform_work_with_retries()
            if ok:
                _anchor_t0 = start
                _anchor_set = True
                _schedule_times = _build_schedule(start)
                return True
            gevent.sleep(0.05)

        return False

    @task
    def work_task(self):
        global _anchor_set

        with _anchor_lock:
            if not _anchor_set:
                if not self._anchor_work():
                    raise StopUser()

        while True:
            target = _next_schedule_time()
            if target is None:
                gevent.sleep(1)
                continue

            delay = target - time.monotonic()
            if delay > 0:
                gevent.sleep(delay)

            self._perform_work_with_retries()


class WorkShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.start_time = time.monotonic()

    def tick(self):
        now = time.monotonic()

        if _anchor_set and _anchor_t0 is not None and now >= _anchor_t0 + 40:
            return None

        if not _anchor_set and now - self.start_time > 15:
            return None

        if now - self.start_time > 60:
            return None

        return (2, 2)
